@import url('https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700;800&display=swap');

:root {
  --bg-primary: #0D1B2A;
  --bg-secondary: #1B2838;
  --bg-tertiary: #15295A;
  --accent-blue-light: #00B4D8;
  --accent-blue-dark: #0077B6;
  --accent-green: #6CC24A;
  --text-primary: #FFFFFF;
  --text-secondary: #B0BEC5;
  --border-color: rgba(255, 255, 255, 0.1);
  --font-family: 'Inter', sans-serif;
  --transition: all 0.3s ease;
}

* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

body {
  font-family: var(--font-family);
  background-color: var(--bg-primary);
  color: var(--text-primary);
  line-height: 1.6;
  overflow-x: hidden;
}

a {
  color: var(--accent-blue-light);
  text-decoration: none;
  transition: var(--transition);
}

a:hover {
  color: var(--accent-blue-dark);
}

ul {
  list-style: none;
}

.container {
  width: 100%;
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 2rem;
}

/* Header & Nav */
header {
  position: sticky;
  top: 0;
  background-color: rgba(13, 27, 42, 0.95);
  backdrop-filter: blur(10px);
  z-index: 1000;
  border-bottom: 1px solid var(--border-color);
  padding: 1rem 0;
}

.nav-container {
  display: flex;
  justify-content: space-between;
  align-items: center;
}

.logo {
  font-size: 1.5rem;
  font-weight: 700;
  color: var(--text-primary);
  display: flex;
  align-items: center;
  gap: 0.5rem;
}

.logo span {
  color: var(--accent-blue-light);
}

.nav-links {
  display: flex;
  gap: 2rem;
  align-items: center;
}

.nav-links a {
  color: var(--text-primary);
  font-weight: 500;
}

.nav-links a:hover {
  color: var(--accent-blue-light);
}

/* Dropdown */
.dropdown {
  position: relative;
}

.dropdown-menu {
  display: none;
  position: absolute;
  top: 100%;
  left: 0;
  background-color: var(--bg-secondary);
  border: 1px solid var(--border-color);
  border-radius: 4px;
  min-width: 200px;
  flex-direction: column;
  box-shadow: 0 10px 30px rgba(0,0,0,0.5);
}

.dropdown:hover .dropdown-menu {
  display: flex;
}

.dropdown-menu a {
  padding: 1rem;
  display: block;
  border-bottom: 1px solid var(--border-color);
}
.dropdown-menu a:last-child {
  border-bottom: none;
}
.dropdown-menu a:hover {
  background-color: var(--bg-tertiary);
}

/* Buttons */
.btn {
  display: inline-block;
  padding: 0.75rem 1.5rem;
  border-radius: 4px;
  font-weight: 600;
  text-align: center;
  cursor: pointer;
  border: none;
  transition: var(--transition);
}

.btn-primary {
  background-color: var(--accent-blue-light);
  color: #000;
}

.btn-primary:hover {
  background-color: var(--accent-blue-dark);
  color: #fff;
}

.btn-secondary {
  background-color: transparent;
  color: var(--accent-blue-light);
  border: 1px solid var(--accent-blue-light);
}

.btn-secondary:hover {
  background-color: var(--accent-blue-light);
  color: #000;
}

/* Typography Sections */
.section {
  padding: 6rem 0;
}

.section-header {
  text-align: center;
  margin-bottom: 4rem;
}

.section-title {
  font-size: 2.5rem;
  font-weight: 800;
  margin-bottom: 1rem;
  background: linear-gradient(90deg, #fff, var(--text-secondary));
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
}

.section-subtitle {
  color: var(--text-secondary);
  font-size: 1.125rem;
  max-width: 800px;
  margin: 0 auto;
}

/* Hero Section */
.hero {
  padding: 8rem 0;
  text-align: center;
  background: radial-gradient(circle at center, var(--bg-secondary) 0%, var(--bg-primary) 100%);
  position: relative;
  overflow: hidden;
}

.hero::before {
  content: '';
  position: absolute;
  top: -50%;
  left: -50%;
  width: 200%;
  height: 200%;
  background: url('data:image/svg+xml;utf8,<svg width="40" height="40" xmlns="http://www.w3.org/2000/svg"><circle cx="2" cy="2" r="1.5" fill="%23ffffff" fill-opacity="0.05"/></svg>') repeat;
  z-index: 0;
}

.hero .container {
  position: relative;
  z-index: 1;
}

.hero h1 {
  font-size: 4rem;
  font-weight: 800;
  line-height: 1.1;
  margin-bottom: 1.5rem;
  text-transform: uppercase;
}

.hero p {
  font-size: 1.25rem;
  color: var(--text-secondary);
  max-width: 800px;
  margin: 0 auto 3rem;
}

.hero-btns {
  display: flex;
  gap: 1rem;
  justify-content: center;
}

/* Banner */
.banner {
  background: linear-gradient(90deg, var(--bg-tertiary), var(--accent-blue-dark));
  padding: 2rem 0;
  text-align: center;
}
.banner p {
  font-size: 1.25rem;
  font-weight: 600;
  margin-bottom: 1rem;
}

/* Cards Grid */
.grid-2 { display: grid; grid-template-columns: repeat(2, 1fr); gap: 2rem; }
.grid-3 { display: grid; grid-template-columns: repeat(3, 1fr); gap: 2rem; }

.card {
  background-color: var(--bg-secondary);
  border: 1px solid var(--border-color);
  border-radius: 8px;
  padding: 2.5rem;
  transition: var(--transition);
  position: relative;
  overflow: hidden;
}

.card:hover {
  transform: translateY(-5px);
  border-color: var(--accent-blue-light);
  box-shadow: 0 10px 30px rgba(0,180,216,0.1);
}

.card h3 {
  font-size: 1.5rem;
  margin-bottom: 1rem;
  color: var(--accent-blue-light);
}

.card p {
  color: var(--text-secondary);
}

/* Tabs */
.tabs-nav {
  display: flex;
  justify-content: center;
  gap: 1rem;
  margin-bottom: 3rem;
  flex-wrap: wrap;
}

.tab-btn {
  background: var(--bg-secondary);
  border: 1px solid var(--border-color);
  color: var(--text-secondary);
  padding: 0.75rem 1.5rem;
  border-radius: 30px;
  cursor: pointer;
  font-weight: 600;
  transition: var(--transition);
}

.tab-btn.active, .tab-btn:hover {
  background: var(--accent-blue-light);
  color: #000;
  border-color: var(--accent-blue-light);
}

.tab-content {
  display: none;
  animation: fadeIn 0.5s ease;
}

.tab-content.active {
  display: block;
}

@keyframes fadeIn {
  from { opacity: 0; transform: translateY(10px); }
  to { opacity: 1; transform: translateY(0); }
}

/* Accordion */
.accordion {
  display: flex;
  flex-direction: column;
  gap: 1rem;
}

.accordion-item {
  background-color: var(--bg-secondary);
  border: 1px solid var(--border-color);
  border-radius: 4px;
  overflow: hidden;
}

.accordion-header {
  padding: 1.5rem;
  cursor: pointer;
  display: flex;
  justify-content: space-between;
  align-items: center;
  font-weight: 600;
  font-size: 1.25rem;
  transition: var(--transition);
}

.accordion-header:hover {
  background-color: var(--bg-tertiary);
}

.accordion-header.active {
  color: var(--accent-blue-light);
  border-bottom: 1px solid var(--border-color);
}

.accordion-icon {
  transition: transform 0.3s ease;
}

.accordion-header.active .accordion-icon {
  transform: rotate(45deg);
}

.accordion-content {
  max-height: 0;
  overflow: hidden;
  transition: max-height 0.4s ease;
  background-color: var(--bg-primary);
}

.accordion-body {
  padding: 1.5rem;
  color: var(--text-secondary);
}

/* Stats (Circular & Numbers) */
.stats-container {
  display: flex;
  justify-content: center;
  gap: 4rem;
  flex-wrap: wrap;
}

.stat-item {
  text-align: center;
  width: 250px;
}

.stat-circle {
  width: 150px;
  height: 150px;
  border-radius: 50%;
  background: conic-gradient(var(--accent-blue-light) 0% var(--perc), var(--bg-secondary) var(--perc) 100%);
  display: flex;
  align-items: center;
  justify-content: center;
  margin: 0 auto 1.5rem;
  position: relative;
}

.stat-circle::after {
  content: '';
  position: absolute;
  width: 130px;
  height: 130px;
  background-color: var(--bg-primary);
  border-radius: 50%;
}

.stat-value {
  position: relative;
  z-index: 1;
  font-size: 2.5rem;
  font-weight: 800;
  color: #fff;
}

.stat-label {
  color: var(--text-secondary);
  font-size: 1.1rem;
}

/* Progress Bars */
.timeline {
  display: flex;
  flex-direction: column;
  gap: 2rem;
  max-width: 800px;
  margin: 0 auto;
}

.timeline-item {
  background: var(--bg-secondary);
  padding: 2rem;
  border-radius: 8px;
}

.timeline-header {
  display: flex;
  justify-content: space-between;
  margin-bottom: 1rem;
  font-weight: 700;
  font-size: 1.25rem;
}

.timeline-time {
  color: var(--accent-green);
}

.progress-track {
  width: 100%;
  height: 8px;
  background: var(--bg-primary);
  border-radius: 4px;
  overflow: hidden;
}

.progress-bar {
  height: 100%;
  background: var(--accent-green);
  border-radius: 4px;
}

/* Carousel */
.carousel-container {
  position: relative;
  max-width: 900px;
  margin: 0 auto;
  overflow: hidden;
  background: var(--bg-tertiary);
  padding: 3rem;
  border-radius: 8px;
  border: 1px solid var(--border-color);
}

.carousel-track {
  display: flex;
  transition: transform 0.5s ease-in-out;
}

.testimonial {
  min-width: 100%;
  padding: 0 2rem;
  text-align: center;
}

.testimonial-text {
  font-size: 1.5rem;
  font-style: italic;
  margin-bottom: 2rem;
}

.testimonial-author {
  color: var(--accent-blue-light);
  font-weight: 600;
}

.carousel-dots {
  display: flex;
  justify-content: center;
  gap: 0.5rem;
  margin-top: 2rem;
}

.dot {
  width: 12px;
  height: 12px;
  background: var(--border-color);
  border-radius: 50%;
  cursor: pointer;
}

.dot.active {
  background: var(--accent-blue-light);
}

/* Diagrams (CSS-based) */
.diagram {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 2rem;
  padding: 4rem 2rem;
  background: var(--bg-secondary);
  border-radius: 12px;
  border: 1px solid var(--border-color);
}
.diagram-block {
  flex: 1;
  text-align: center;
  padding: 2rem;
  background: var(--bg-tertiary);
  border: 2px solid var(--accent-blue-dark);
  border-radius: 8px;
  position: relative;
  z-index: 2;
}
.diagram-block h4 {
  font-size: 1.25rem;
  margin-bottom: 0.5rem;
  color: var(--accent-blue-light);
}
.diagram-arrow {
  flex-grow: 1;
  height: 4px;
  background: var(--accent-blue-light);
  position: relative;
  z-index: 1;
  min-width: 50px;
}
.diagram-arrow::after {
  content: '';
  position: absolute;
  right: -5px;
  top: -6px;
  border-top: 8px solid transparent;
  border-bottom: 8px solid transparent;
  border-left: 12px solid var(--accent-blue-light);
}

/* Forms */
.form-container {
  max-width: 600px;
  margin: 0 auto;
  background: var(--bg-secondary);
  padding: 3rem;
  border-radius: 8px;
  border: 1px solid var(--border-color);
}
.form-group {
  margin-bottom: 1.5rem;
}
.form-group label {
  display: block;
  margin-bottom: 0.5rem;
  color: var(--text-secondary);
  font-weight: 500;
}
.form-control {
  width: 100%;
  padding: 1rem;
  background: var(--bg-primary);
  border: 1px solid var(--border-color);
  border-radius: 4px;
  color: var(--text-primary);
  font-family: inherit;
}
.form-control:focus {
  outline: none;
  border-color: var(--accent-blue-light);
}
.form-error {
  color: #ff5252;
  font-size: 0.875rem;
  margin-top: 0.25rem;
  display: none;
}
.form-group.error .form-control { border-color: #ff5252; }
.form-group.error .form-error { display: block; }

/* Table */
table {
  width: 100%;
  border-collapse: collapse;
  margin-top: 2rem;
}
th, td {
  padding: 1rem;
  text-align: left;
  border-bottom: 1px solid var(--border-color);
}
th {
  background-color: var(--bg-secondary);
  color: var(--accent-blue-light);
}
tr:hover {
  background-color: rgba(255,255,255,0.02);
}

/* Footer */
footer {
  background-color: var(--bg-secondary);
  padding: 4rem 0 2rem;
  border-top: 1px solid var(--border-color);
}
.footer-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 2rem;
  margin-bottom: 3rem;
}
.footer-col h4 {
  color: var(--text-primary);
  margin-bottom: 1.5rem;
}
.footer-col ul li {
  margin-bottom: 0.75rem;
}
.footer-col ul li a {
  color: var(--text-secondary);
}
.footer-col ul li a:hover {
  color: var(--accent-blue-light);
}
.footer-bottom {
  text-align: center;
  padding-top: 2rem;
  border-top: 1px solid var(--border-color);
  color: var(--text-secondary);
}

/* Cookie Banner */
.cookie-banner {
  position: fixed;
  bottom: 0;
  left: 0;
  width: 100%;
  background: var(--bg-tertiary);
  padding: 1.5rem;
  display: flex;
  justify-content: space-between;
  align-items: center;
  z-index: 2000;
  box-shadow: 0 -5px 20px rgba(0,0,0,0.5);
  transform: translateY(100%);
  transition: transform 0.5s ease;
}
.cookie-banner.show {
  transform: translateY(0);
}
.cookie-text {
  max-width: 800px;
}
.cookie-actions {
  display: flex;
  gap: 1rem;
}

/* Lists with Icons */
.feature-list {
  list-style: none;
}
.feature-list li {
  display: flex;
  align-items: flex-start;
  gap: 1rem;
  margin-bottom: 1rem;
  font-size: 1.125rem;
}
.feature-list li::before {
  content: '✓';
  color: var(--accent-green);
  font-weight: bold;
  font-size: 1.5rem;
  line-height: 1;
}

/* Responsive */
@media (max-width: 768px) {
  .hero h1 { font-size: 2.5rem; }
  .grid-2, .grid-3, .footer-grid { grid-template-columns: 1fr; }
  .diagram { flex-direction: column; }
  .diagram-arrow { width: 4px; height: 50px; min-width: auto; }
  .diagram-arrow::after { top: 100%; left: -4px; border-left: 8px solid transparent; border-right: 8px solid transparent; border-top: 12px solid var(--accent-blue-light); border-bottom: none; }
  .cookie-banner { flex-direction: column; text-align: center; gap: 1rem; }
  .nav-links { display: none; } /* Add mobile menu JS if needed */
}

document.addEventListener('DOMContentLoaded', () => {

  // Tabs Logic
  const setupTabs = (tabNavClass, tabContentClass) => {
    const tabBtns = document.querySelectorAll(`.${tabNavClass} .tab-btn`);
    const tabContents = document.querySelectorAll(`.${tabContentClass}`);

    tabBtns.forEach(btn => {
      btn.addEventListener('click', () => {
        const targetId = btn.getAttribute('data-target');

        tabBtns.forEach(b => b.classList.remove('active'));
        tabContents.forEach(c => c.classList.remove('active'));

        btn.classList.add('active');
        document.getElementById(targetId).classList.add('active');
      });
    });
  };

  setupTabs('industry-tabs', 'industry-content');
  setupTabs('integration-tabs-nav', 'integration-content');
  setupTabs('security-tabs-nav', 'security-content');

  // Accordion Logic
  const accordionHeaders = document.querySelectorAll('.accordion-header');
  accordionHeaders.forEach(header => {
    header.addEventListener('click', () => {
      const content = header.nextElementSibling;
      const isActive = header.classList.contains('active');

      // Close all
      document.querySelectorAll('.accordion-header').forEach(h => {
        h.classList.remove('active');
        h.nextElementSibling.style.maxHeight = null;
      });

      // Toggle current
      if (!isActive) {
        header.classList.add('active');
        content.style.maxHeight = content.scrollHeight + 'px';
      }
    });
  });

  // Carousel Logic
  const track = document.querySelector('.carousel-track');
  if (track) {
    const slides = Array.from(track.children);
    const dotsNav = document.querySelector('.carousel-dots');
    const dots = Array.from(dotsNav.children);

    const updateCarousel = (index) => {
      track.style.transform = `translateX(-${index * 100}%)`;
      dots.forEach(d => d.classList.remove('active'));
      dots[index].classList.add('active');
    };

    dots.forEach((dot, index) => {
      dot.addEventListener('click', () => updateCarousel(index));
    });
  }

  // Cookie Banner Logic
  const cookieBanner = document.getElementById('cookie-banner');
  if (cookieBanner) {
    const hasConsented = localStorage.getItem('cookieConsent');
    if (!hasConsented) {
      setTimeout(() => cookieBanner.classList.add('show'), 1000);
    }

    document.getElementById('accept-cookies')?.addEventListener('click', () => {
      localStorage.setItem('cookieConsent', 'true');
      cookieBanner.classList.remove('show');
    });

    document.getElementById('decline-cookies')?.addEventListener('click', () => {
      localStorage.setItem('cookieConsent', 'false');
      cookieBanner.classList.remove('show');
    });
  }

  // Form Validation Logic
  const demoForm = document.getElementById('demo-form');
  if (demoForm) {
    demoForm.addEventListener('submit', (e) => {
      e.preventDefault();
      let isValid = true;
      const inputs = demoForm.querySelectorAll('.form-control[required]');

      inputs.forEach(input => {
        const group = input.parentElement;
        if (!input.value.trim()) {
          group.classList.add('error');
          isValid = false;
        } else {
          group.classList.remove('error');
        }
      });

      if (isValid) {
        // Simulate submission
        demoForm.innerHTML = '<div class="success-message"><h3>Thank you!</h3><p>Your demo request has been submitted successfully. Our team will contact you shortly.</p></div>';
      }
    });
  }
});

